--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `orders` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `order_no` varchar(20) NOT NULL,
  `user_id` int(10) unsigned DEFAULT NULL,
  `payment_gateway` varchar(191) NOT NULL,
  `shiped_date` date DEFAULT NULL,
  `shipped_no` varchar(10) DEFAULT NULL,
  `shipping_method` int(10) unsigned DEFAULT NULL,
  `status` enum('Awaiting Payment','Awaiting Shipment','Shipped','Cancelled','Refunded','Completed','Awaiting Confirm') NOT NULL DEFAULT 'Awaiting Payment',
  `delivery_price` int(10) DEFAULT NULL,
  `total_price` int(11) NOT NULL,
  `name_address` varchar(191) DEFAULT NULL,
  `address` varchar(191) DEFAULT NULL,
  `city` varchar(191) DEFAULT NULL,
  `province` varchar(191) DEFAULT NULL,
  `postcode` varchar(191) DEFAULT NULL,
  `tel_number` varchar(191) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `orders_user_id_foreign` (`user_id`),
  KEY `shipping_method` (`shipping_method`),
  CONSTRAINT `orders_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2148 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

