INSERT INTO `products` VALUES (897,'ลวดเชื่อมสแตนเลสไฟฟ้า GEMINI 308L (E308L-16)','ลวดเชื่อมสเตนเลส เจมินี่ Gemini 308L (E308L-16) เป็นสแตนเลสกลุ่มออสเทนนิติก สารพอกหุ้มประเภทไทเทเนีย มีธาตุคาร์บอนผสมในปริมาณต่ำ ใช้สำหรับงานเชื่อมสเตนเลสทั่วไป','<h1><span style=\"font-size: 14.4px; color: #212529;\"><span id=\"docs-internal-guid-2a63c9ab-7fff-7589-45e6-9616b01239da\"><a href=\"https://www.udo.co.th/product/detail/yawata-308l-16\"><span style=\"font-size: 18pt; color: #1155cc; background-color: transparent;\">ลวดเชื่อมสแตนเลส</span></a></span></span></h1>\r\n<h2><span style=\"color: #ff0000;\">***สั่งซื้อสินค้าจำนวน ติดต่อสอบถามเพิ่มเติมค่ะ***</span></h2>\r\n<p><span class=\"textred14\"><span lang=\"TH\" style=\"color: #b10000;\"><a title=\"ลวดเชื่อม\" href=\"https://www.udo.co.th/category_product/%E0%B8%81%E0%B8%A5%E0%B8%B8%E0%B9%88%E0%B8%A1%E0%B8%A5%E0%B8%A7%E0%B8%94%E0%B9%80%E0%B8%8A%E0%B8%B7%E0%B9%88%E0%B8%AD%E0%B8%A1\">ลวดเชื่อม</a>เจมินี่ </span></span><span class=\"textred14\"><span style=\"color: #b10000;\">308L</span></span><span style=\"color: #b10000;\"><br /> <span class=\"textred14\"><span lang=\"TH\">ลวดเชื่อม สำหรับเหล็กสแตนเลส</span></span></span></p>\r\n<p style=\"margin-bottom: .0001pt; line-height: 15.0pt;\"><span lang=\"TH\" style=\"font-size: 12.0pt; color: #171717;\">ลวดเชื่อมเจมินี่ </span><span style=\"font-size: 12.0pt; color: #171717;\">308L <span lang=\"TH\">เป็นลวดเชื่อมสเตนเลสออส</span></span><span style=\"font-size: 16px; color: #171717;\">เท</span><span lang=\"TH\" style=\"font-size: 12pt; color: #171717;\">นนิติก สารพอกหุ้มประเภทไทเท</span><span lang=\"TH\" style=\"font-size: 12pt; color: #171717;\">เนีย มีธาตุคาร์บอนผสมในปริมาณต่า ใช้สาหรับงานเชื่อมสเตนเลสทั่วไป สามารถเชื่อม&nbsp;</span><span lang=\"TH\" style=\"font-size: 12pt; color: #171717;\">เหล็กที่มีส่วนผสมของธาตุโครเมียม-นิเกิล แนวเชื่อมทนต่อการกัดกร่อนได้ดี ในสภาวะ&nbsp;</span><span lang=\"TH\" style=\"font-size: 12pt; color: #171717;\">อากาศปกติ และทนต่อการกัดกร่อนของกรดอ่อนๆได้ เหมาะกับงานเชื่อมสเตนเลส </span><span style=\"font-size: 12pt; color: #171717;\">AISI 302, 304, 304 L </span><span lang=\"TH\" style=\"font-size: 12pt; color: #171717;\">และ </span><span style=\"font-size: 12pt; color: #171717;\">304 LN</span></p>\r\n<p style=\"margin-bottom: .0001pt; line-height: 15.0pt;\"><span class=\"textred14\"><span lang=\"TH\" style=\"font-size: 12.0pt; color: #b10000;\">คุณสมบัติของแนวเชื่อม</span></span></p>\r\n<p style=\"margin-bottom: .0001pt; line-height: 15.0pt;\">&nbsp;</p>\r\n<table class=\"MsoNormalTable\" style=\"border: outset #CCCCCC 1.0pt;\" border=\"1\" width=\"98%\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"border: inset #CCCCCC 1.0pt;\" colspan=\"2\">\r\n<p class=\"MsoNormal\" align=\"center\"><span lang=\"TH\" style=\"font-size: 12.0pt; color: #282828;\">ส่วนผสมทางเคมี (%)</span></p>\r\n</td>\r\n<td style=\"border: inset #CCCCCC 1.0pt;\" colspan=\"2\">\r\n<p class=\"MsoNormal\" align=\"center\"><span lang=\"TH\" style=\"font-size: 12.0pt; color: #282828;\">คุณสมบัติทางกล</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: inset #CCCCCC 1.0pt;\">\r\n<p class=\"MsoNormal\" align=\"center\"><span style=\"font-size: 12.0pt; color: #282828;\">C</span></p>\r\n</td>\r\n<td style=\"border: inset #CCCCCC 1.0pt;\">\r\n<p class=\"MsoNormal\" align=\"center\"><span style=\"font-size: 12.0pt; color: #282828;\">0.01</span></p>\r\n</td>\r\n<td style=\"border: inset #CCCCCC 1.0pt;\" valign=\"top\">\r\n<p class=\"MsoNormal\"><span style=\"font-size: 12.0pt; color: #282828;\">Yield stress</span></p>\r\n</td>\r\n<td style=\"border: inset #CCCCCC 1.0pt;\" valign=\"top\">\r\n<p class=\"MsoNormal\" align=\"center\"><span style=\"font-size: 12.0pt; color: #282828;\">520 N/mm<sup>2</sup></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: inset #CCCCCC 1.0pt;\">\r\n<p class=\"MsoNormal\" align=\"center\"><span style=\"font-size: 12.0pt; color: #282828;\">Mn</span></p>\r\n</td>\r\n<td style=\"border: 