INSERT INTO `settings` VALUES (4,'admin.google_analytics_tracking_id','Google Analytics Tracking ID',NULL,'','text',4,'Admin'),(6,'admin.title','Admin Title','UDO BACKOFFICE','','text',1,'Admin'),(7,'admin.description','Admin Description','Backoffice Loyalty Group','','text',2,'Admin'),(8,'admin.loader','Admin Loader',NULL,'','image',3,'Admin'),(9,'admin.icon_image','Admin Icon Image',NULL,'','image',4,'Admin'),(10,'admin.google_analytics_client_id','Google Analytics Client ID (used for admin dashboard)','AIzaSyB09mMSc1AQKcYS8oB9uAHlv6rw7Qbj2gM','','text',1,'Admin'),(17,'contact.tel','Telephone Number','062-815-9999',NULL,'text',10,'Contact'),(18,'contact.line','Line ID','@udowelding',NULL,'text',11,'Contact'),(19,'contact.email','Email','bee0834@me.com',NULL,'text',12,'Contact'),(20,'footer.footer_about','Footer About','<p>ศูนย์รวมเครื่องมือช่าง ลวดเชื่อม, เครื่องเชื่อมและตัด,ท่อบรรจุก๊าซและวาล์ว, อะไหล่เครื่องเชื่อมและเครื่องตัด, เกจ์ปรับแรงดันอุปกรณ์เชื่อมตัด และเผาแก๊ส, อะไหล่สิ้นเปลือง น้ำยาเคมีภัณฑ์, ใบตัดและใบเจียรคุณภาพสูง มากกว่า 1,000 รายการ</p>',NULL,'rich_text_box',21,'Footer'),(21,'footer.footer_contact','Footer Contact','<p>บริษัท อุดมสวัสดิ์อ๊อกซิเย่น จำกัด&nbsp; <br /> 149-153 ถ.จันทน์ แขวงทุ่งวัดดอน เขตสาทร กทม. 10120</p>\r\n<p>เปิดบริการวันจันทร์-เสาร์ตั้งแต่ 8:00 &ndash;17:00 น.&nbsp; <br /> TEL : 0-2674-9313, 0-2674-9241, 062-815-9999&nbsp;&nbsp;<br /> FAX : 0-2212-2731&nbsp;</p>',NULL,'rich_text_box',14,'Footer'),(22,'site.title','Site Title','ผู้นำเข้าและจัดจำหน่าย ลวดเชื่อม KOBE YAWATA HUNDAI POWERWELD KISWEL ลวดเชื่อมเกรดพิเศษทุกชนิด เกจ์ปรับแรงดัน ท่อบรรจุก๊าซ อะไหล่เครื่องตัดพลาสม่า ใบตัดใบเจียร ราคาปลีกและส่ง พร้อมให้คำปรึกษา','','text',1,'Site'),(23,'site.description','Site Description','ยูดีโอ จำหน่ายลวดเชื่อมทุกชนิด  ลวดเชื่อมเกรดพิเศษ เกจปรับแรงดัน ท่อบรรจุก๊าซ อะไหล่เครื่องตัดพลาสม่า ใบเจียร ราคาปลีกและส่ง ประสบการณ์เฉพาะด้าน มากกว่า 40 ปี ลูกค้าภาครัฐและเอกชนให้ความไว้วางใจกว่า 100 ราย','','text',2,'Site'),(24,'site.logo','Site Logo','settings\\May2018\\UfdQimg5T62pwmjlah4k.png','','image',4,'Site'),(25,'site.google_analytics_tracking_id','Google Analytics Tracking ID','UA-118952386-1','','text',22,'Site'),(26,'admin.bg_image','Admin Background Image',NULL,'','image',5,'Admin'),(27,'policy.tac','ข้อกำหนดและเงื่อนไข','<p><span style=\"font-size: 14px; font-weight: 400;\">หน้านี้ได้ให้ข้อมูลการซื้อขายของ บริษัท อุดมสวัสดิ์อ๊อกซิเย่น จำกัด ที่ใช้ชื่อ udo.co.th (\"udo.co.th\", \"เรา\", \"ของเรา\" และ/หรือ \"พวกเรา\") และข้อกำหนดและเงื่อนไข (\"ข้อกำหนด\") ในการขายสินค้าของเราตามข้อ&nbsp;</span><span style=\"font-size: 14px; font-weight: 400;\">(\"สินค้า\") ผ่านเว็บไซต์ของเรา (\"เว็บไซต์ของเรา\") ให้ท่าน ข้อกำหนดเหล่านี้จะใช้กับทุกสัญญาสำหรับการขายสินค้าระหว่างเรากับท่าน&nbsp; ก่อนที่จะใช้เว็บไซต์ของเรา โปรดอ่านข้อกำหนดเหล่านี้อย่างละเอียดถี่ถ้วนและตรวจสอบให้แน่ใจว่าท่านเข้าใจ</span></p>\r\n<p><span style=\"font-size: 14px; font-weight: 400;\">โปรดทราบว่า ก่อนการสั่งซื้อหรือชำระเงิน ท่านจะได้รับคำถามว่ายอมรับข้อกำหนดเหล่านี้หรือไม่ หากท่านปฏิเสธที่จะยอมรับข้อกำหนดเหล่านี้ ท่านจะไม่สามารถสั่งซื้อสินค้าใดๆ จากเว็บไซต์ของเราหรือทำการชำระเงินค่าสินค้านั้นได้</span></p>\r\n<p><span style=\"font-size: 14px; font-weight: 400;\">ท่านควรดูอ่านและพิมพ์สำเนาของข้อกำหนดเหล่านี้หรือบันทึกไว้ในคอมพิวเตอร์ เพื่อใช้อ้างอิงในอนาคต เราอาจจะแก้ไขข้อกำหนดเหล่านี้เป็นครั้งคราวดังที่ได้ระบุไว้ด้านล่างนี้ ทุกครั้งที่ท่านต้องการสั่งซื้อสินค้าหรือใช้เว็บไซต์ของเรา โปรดตรวจสอบข้อกำหนดเหล่านี้เพื่อให้แน่ใจว่าท่านเข้าใจในข้อกำหนดที่จะใช้ ณ เวลาดังกล่าว</span></p>\r\n<p><strong><span style=\"font-size: 14px;\">ข้อมูลเกี่ยวกับเรา</span></strong></p>\r\n<p style=\"padding-left: 30px;\"><span style=\"font-size: 14px; font-weight: 400;\">&nbsp;เราคือ บริษัท อุดมสวัสดิ์อ๊อกซิเย่น จำกัด ทำการค้าในชื่อของ udo.co.th ซึ่งเป็นบริษัทจดทะเบียนในประเทศไทย เลขทะเบียนบริษัท ................... และมีสำนักงานจดทะเบียนอยู่ที่ 149-153 ถ.จันทน์ แขวงทุ่งวัดดอน เขตสาทร กทม. 10120</span></p>\r\n<p><strong><span style=\"font-size: 14px;\">ติดต่อเรา</span></strong></p>\r\n<ul>\r\n<li style=\"padding-left: 30px;\"><span style=\"font-size: 14px; font-weight: 400;\">หากท่านต้องการติดต่อเราไม่ว่าจะด้วยเหตุผลใดก็ตาม รวมถึงมีข้อร้องเรียน โปรดส่งอีเมล์มาที่ :&nbsp;</span><span style=\"font-size: 14px; font-weight: 400;\">bee0834@me.com/&nbsp; Line ID:&nbsp; @udowelding/&nbsp; โทรศัพท์ : 062-815-9999</span></li>\r\n<li style=\"padding-left: 30px;\"><span style=\"font-size: 14px; font-weight: 400;\">หากเราต้องการติดต่อกับท่านหรือแจ้งเป็นลายลักษณ์อักษร ทางเราจะทำการส่งอีเมล์หรือส่งหนังสือแจ้งไปทางไปรษณีย์ไปตามที่อยู่ที่ท่านได้แจ้งไว้ในใบสั่งซื้อของท่าน</span></li>\r\n</ul>\r\n<p><strong><span style=\"font-size: 14px;\">การสั่งซื้อบนเว็บไซต์</span><span style=\"font-size: 14px;\">กับเรา</span></strong></p>\r\n<ul>\r\n<li><span style=\"font-size: 14px; font-weight: 400;\">ท่านยอมรับว่าเป็นธุรกรรมระหว่างท่านกับเรา ท่านยังยอมรับอีกว่า เมื่อเราได้ยืนยันความถูกต้องและความสมบูรณ์ของข้อมูลที่ท่านให้ไว้แล้ว ทางเราจะซื้อสินค้าวัตถุประสงค์ในการจำหน่ายให้กับท่านในทันทีตามจำนวนเงินที่แสดงและตกลงกันเมื่อท่านส่งคำสั่งซื้อของท่านเราจะเป็นผู้รับผิดชอบในการดำเนินการส่งสินค้าตามคำสั่งซื้อของคุณ</span></li>\r\n<li>เว็บไซต์ของเราจะแนะนำขั้นตอนที่ท่านต้องทำเพื่อส่งคำสั่งซื้อและชำระเงินให้กับเรา กระบวนการสั่งซื้อของเราเอื้ออำนวยให้ท่านตรวจสอบและแก้ไขข้อผิดพลาดก่อนส่งคำสั่งซื้อให้กับเรา กรุณาอ่านและตรวจสอบคำสั่งซื้อในแต่ละหน้าของกระบวนการสั่งซื้อ</li>\r\n<li>หลังจากที่ท่านได้ส่งคำสั่งซื้อ ท่านจะได้รับอีเมล์จากเราแจ้งว่าได้รับคำสั่งซื้อของท่าน ท่านจะได้รับใบแจ้งหนี้หลังจากมีการดำเนินการคำสั่งซื้อและการทำสัญญาระหว่างท่านกับเราจะเกิดขึ้น ณ จุดนี้</li>\r\n<li>ท่านทราบว่าเราได้รับอนุญาตให้ตรวจสอบความถูกต้อง และข้อมูลการชำระเงินที่ท่านให้ไว้ ถ้าเราไม่สามารถตรวจสอบข้อมูลดังกล่าวได้โดยอัตโนมัติ พนักงานของเราจะติดต่อกับท่านหรือธนาคารที่ออกบัตรเครดิต ของท่านเพื่อขอให้ยืนยันตัวตนและ/หรือเจตนาการสั่งซื้อ</li>\r\n<li style=\"padding-left: 30px;\">&nbsp;</li>\r\n</ul>',NULL,'rich_text_box',15,'Policy'),(28,'policy.private_policy','นโยบายความเป็นส่วนตัว','<p>ข้อ 1 วัตถุประสงค์</p>\r\n<p>วัตถุประสงค์ของข้อกำหนดและเงื่อนไข (\"ข้อตกลง\" นี้) มีขึ้นเพื่อกำหนดสิทธิและหน้าที่และสาระสำคัญ ระหว่างบุคคลที่ทำการขายสินค้าหรือบริการกับบุคคลอื่นๆ สิทธิและหน้าที่ และสาระสำคัญ ระหว่างสมาชิกกับบริษัท และขั้นตอนสำหรับการใช้บริการโดยสมาชิก เป็นต้น ซึ่งเชื่อมโยงกับการใช้บริการต่างๆ ที่เกี่ยวข้องกับอีคอมเมิร์ซ (\"บริการ\") ที่จัดหาให้โดย&nbsp;UDO (www.udo.co.th)&nbsp;ต่อไปนี้จะเรียกว่า&nbsp;UDO &nbsp;ที่ดำเนินการโดย&nbsp;UDO (www.udo.co.th)&nbsp;(\"บริษัท\") ดังที่กำหนดไว้ด้านล่างนี้</p>\r\n<p>ข้อ 2 คำนิยาม</p>\r\n<p>ข้อกำหนดต่อไปนี้มีความหมายตามลำดับดังต่อไปนี้:</p>\r\n<p>1) \"UDO (www.udo.co.th)\" หมายถึงเว็บไซต์ที่มีไว้สำหรับระบบอีคอมเมิร์ซแบบเรียลไทม์และการดำเนินการของเว็บไซต์ที่ให้บริการโดยบริษัท สำหรับการทำรายการสินค้าและบริการ (รวมกันเรียกว่า \"สินค้า\")</p>\r\n<p>2) \"ผู้ใช้\" หมายถึงสมาชิกและผู้ที่ไม่ได้เป็นสมาชิกซึ่งได้รับบริการที่จัดหาให้โดยบริษัทตามข้อตกลงนี้</p>\r\n<p>3) \"สมาชิก\" หมายถึงบุคคลธรรมดาหรือธุรกิจที่ได้ลงทะเบียนตนเองเป็นสมาชิกตามขั้นตอนของการลงทะเบียนที่สร้างขึ้นโดยบริษัท และผู้ที่ได้รับการจัดหาข้อมูลเกี่ยวกับบริษัทอย่างสม่ำเสมอ และสามารถใช้บริการที่จัดหาให้โดยบริษัท สมาชิกประกอบด้วยสมาชิกทั่วไปและสมาชิกผู้ขายดังต่อไปนี้:</p>\r\n<p>4) \"สมาชิกทั่วไป (ลูกค้าที่ซื้อสินค้า)\" หมายถึงสมาชิกใดๆ ที่มีสิทธิ์ใช้บริการที่จัดหาให้โดย UDO เพื่อซื้อสินค้าและการซื้ออื่นๆ \"สมาชิกผู้ซื้อ&rdquo; คือ มีสิทธิ์ในการลงทะเบียนเป็นสมาชิกเพื่อวัตถุประสงค์ในการซื้อเพียงอย่างเดียว (รวมถึงชาวต่างชาติที่อาศัยอยู่ในประเทศไทย)</p>\r\n<p>5) \"ผู้ไม่ได้เป็นสมาชิก\" หมายถึงบุคคลใดๆ ที่ใช้บริการที่จัดหาให้โดยบริษัทโดยไม่ได้ลงทะเบียนตนเองเป็นสมาชิก</p>\r\n<p>6) \"ID\" หมายถึงตัวอักษร ตัวเลข หรือทั้งตัวอักษรและตัวเลขผสมกันที่เลือกโดยสมาชิกและลงทะเบียนโดยบริษัทสำหรับการยืนยันตัวตนของสมาชิก</p>\r\n<p>7) \"รหัสผ่าน\" หมายถึงตัวอักษรและตัวเลขผสมกันที่เลือกโดยสมาชิกและลงทะเบียนกับบริษัทเพื่อวัตถุประสงค์ในการยืนยันตัวตนของสมาชิกและปกป้องข้อมูลที่เป็นความลับ</p>\r\n<p>8) \"ผู้ให้บริการ\" หมายถึงบุคคลใดๆ ที่บริษัทเลือกเพื่อวัตถุประสงค์ในการดำเนินการและการจัดการโดยรวมของบริการที่จัดหาให้โดยบริษัทได้อย่างราบรื่น</p>\r\n<p>9) \"ผู้ซื้อ\" หมายถึงผู้ใช้ใดๆ ที่ซื้อสินค้าของผู้ขายที่ลงทะเบียนกับบริษัท สิทธิ์ในการซื้อถูกมอบให้กับทั้งสมาชิกทั่วไปและสมาชิกผู้ขายและผู้ที่ไม่ได้เป็นสมาชิก</p>',NULL,'rich_text_box',16,'Policy'),(29,'policy.policy_product','นโยบายเกี่ยวกับสินค้าในการจำหน่าย',NULL,NULL,'rich_text_box',17,'Policy'),(30,'banner-header.text','ข้อความ Header Banner','<h1 style=\"text-align: center;\">THE LEADER OF WELDING PRODUCTS COMPANY</h1>\r\n<h1 style=\"text-align: center;\">ศูนย์รวมอุปกรณ์งานเชื่อม งานตัด ทุกประเภท</h1>',NULL,'rich_text_box',18,'Banner_Header'),(32,'product.promotion','โปรโมชั่น','custom','{\r\n    \"options\" : {\r\n        \"random\": \"แสดงผลแบบ Random\",\r\n        \"custom\": \"แสดงผลตามข้อมูลที่กำหนด\"\r\n    }\r\n}','radio_btn',19,'Product'),(33,'product.recommended','สินค้าแนะนำ','recrandom','{\r\n    \"options\" : {\r\n        \"recrandom\": \"แสดงผลแบบ Random\",\r\n        \"reccustom\": \"แสดงผลตามข้อมูลที่กำหนด\"\r\n    }\r\n}','radio_btn',20,'Product'),(34,'footer.footer_textabout','เกี่ยวกับเรา','<h1>อุดมสวัสดิ์อ๊อกซิเย่น</h1>\r\n<p>บริษัท อุดมสวัสดิ์อ๊อกซิเย่น จำกัด เป็นผู้นำในธุรกิจด้านงานเชื่อม&nbsp; โดยเรามีสินค้าที่เป็นลวดเชื่อมที่สามารถตอบโจทย์งานเชื่อมต่างๆไม่ว่าจะเป็น <a title=\"ลวดเชื่อม\" href=\"https://www.udo.co.th/category_product/กลุ่มลวดเชื่อม \">ลวดเชื่อม</a>ที่ใช้ในงานเชื่อมเหล็ก ลวดเชื่อมแตนเลส ลวดเชื่อมอลูมิเนียม&nbsp; &nbsp;ลวดเชื่อมเหล็กหล่อ ลวดเชื่อมตัดเซาะร่อง นอกจากนั้นยังมีลวดเชื่อมเกรดพิเศษที่ใช้ในงานเชื่อมวัสดุเกรดพิเศษนานาชนิด ลวดเชื่อมทองเหลือง ทองแดงและเงิน ลวดเชื่อมพอกผิวแข็ง ลวดเชื่อมเซาะร่อง เชื่อมทังสเตน มาให้ลูกค้าได้เลือกสรรค์มากมาย</p>\r\n<p>บริษัท อุดมสวัสดิ์อ๊อกซิเย่น จำกัด ยังมีสินค้าประเภทเกจปรับแรงดัน อุปกรณ์การเชื่อมตัดแก๊ส และ ท่อบรรจุก๊าซที่ได้มาตรฐานท่อบรรจุก๊าซของทางเรามีให้เลือกมากมายหลายประเภทหลายขนาด มีทั้งท่อบรรจุก๊าซอ๊อกซิเย่น แก๊สอะเซทีลีน(AC) ก๊าซอาร์กอน และท่อบรรจุก๊าซไนโตรเจนหรือแม้แต่ท่อบรรจุก๊าซที่ใช้ในทางการแพทย์ ทางเราก็มีให้เลือกซื้อ</p>\r\n<p>บริษัท อุดมสวัสดิ์อ๊อกซิเย่นจำกัด จะเป็นผู้นำในธุรกิจด้านงานเชื่อมแต่เราก็ยังมีสินค้าด้านงานตัดงานเจียรอีกด้วย</p>\r\n<p>ถ้าพูดถึงการตัดการเจียร ใบตัด ใบเจียร ก็เป็นสิ่งสำคัญเราควรเลือกซื้อให้เหมาะสมกับงานที่ต้องตัดหรือเจียร ไม่ว่าจะเป็นงาน ตัดเหล็ก เจียรเหล็ก ที่ต้องใช้ ใบตัด ใบเจียร สำหรับเหล็ก งานเจียรกระจกที่ต้องใช้ ใบเจียร กระจก และงานเจียรแสตนเลสที่ต้องใช้ใบเจียรแสตนเลส&nbsp;</p>\r\n<p>ทางเรามีใบเจียรให้เลือกซื้อตามงานที่ลูกค้าจะใช้ ทางด้านงานตัดหลายๆคนคงเคยใช้เครื่องตัดพลาสม่า ปัจจุบันการตัดโลหะด้วยเครื่องตัดพลาสม่าเป็นที่นิยมมากขึ้นเนื่องจากมีความสะดวกรวดเร็วและงานออกมาเรียบร้อย&nbsp; เครื่องตัดพลาสม่า สามารถตัดโลหะได้หลากหลายชนิด ทั้งอลูมิเนียม คาร์บอน สเตนเลส ทองแดง ทองเหลือง บรอนซ์นิกเกิลอัลลอย เซอร์โครเมียม เป็นต้น ซึ่งขบวนการตัดจะแตกต่างกันไปบ้าง ขึ้นอยู่กับความหนาของโลหะและการเลือกใช้ขนาดของหัวตัดให้เหมาะสมกับชิ้นงาน&nbsp;</p>\r\n<p>ที่บริษัท อุดมสวัสดิ์อ๊อกซิเย่น จำกัด มีอะไหล่เครื่องตัดพลาสม่าให้ท่านที่สนใจได้สั่งซื้อไปใช้ในงานตัดที่ต้องการความสะดวกและเรียบร้อย</p>',NULL,'rich_text_box',13,'Footer'),(35,'site.keywords','Site Keywords','ลวดเชื่อม, เกจปรับแรงดัน, ท่อบรรจุก๊าซ, อะไหล่เครื่องตัดพลาสม่า, ใบเจียร, ใบต้ด-ใบเจียร, อุปกรณ์เสริม, ลวดเชื่อมพิเศษ, เกรดพรีเมี่ยม, ลวดเชื่อมนำเข้า, ตู้เชื่อมไฟฟ้า, งานเชื่อม, ตัดพลาสม่า, จำหน่ายลวดเชื่อมทุกชนิด, อุดมสวัสดิ์',NULL,'text',3,'Site'),(36,'contact.facebook','Facebook','https://www.facebook.com/udomsawatoxygen/',NULL,'text',23,'Contact'),(37,'site.bank_account','Bank Account','<p><strong>ชื่อบัญชี</strong> :</p>\r\n<p><strong>ธนาคาร</strong> :</p>\r\n<p><strong>เลขบัญชี</strong> :</p>',NULL,'rich_text_box',24,'Site');
